CREATE TABLE settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE users(id INTEGER PRIMARY KEY,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('manager','staff')),created_at TEXT NOT NULL);
CREATE TABLE sessions(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),token_hash TEXT UNIQUE NOT NULL,csrf_token TEXT NOT NULL,expires_at TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE tables(id INTEGER PRIMARY KEY,label TEXT NOT NULL,seats INTEGER NOT NULL CHECK(seats>0),zone TEXT,join_group TEXT,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE service_windows(id INTEGER PRIMARY KEY,weekday INTEGER NOT NULL CHECK(weekday BETWEEN 0 AND 6),start_time TEXT NOT NULL,end_time TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE closures(id INTEGER PRIMARY KEY,date TEXT UNIQUE NOT NULL,label TEXT);
CREATE TABLE reservations(id INTEGER PRIMARY KEY,reference TEXT UNIQUE NOT NULL,idempotency_key TEXT UNIQUE,status TEXT NOT NULL CHECK(status IN('pending','confirmed','declined','cancelled')),starts_at TEXT NOT NULL,ends_at TEXT NOT NULL,local_date TEXT NOT NULL,local_time TEXT NOT NULL,party_size INTEGER NOT NULL,first_name TEXT NOT NULL,last_name TEXT NOT NULL,email TEXT NOT NULL,phone TEXT NOT NULL,message TEXT,assigned_tables TEXT NOT NULL,cancellation_hash TEXT,cancellation_expires_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,source TEXT NOT NULL);
CREATE INDEX idx_reservations_overlap ON reservations(starts_at,ends_at,status);CREATE INDEX idx_reservations_date ON reservations(local_date,status);CREATE TABLE reservation_history(id INTEGER PRIMARY KEY,reservation_id INTEGER NOT NULL REFERENCES reservations(id),status TEXT NOT NULL,note TEXT,actor TEXT NOT NULL,created_at TEXT NOT NULL);CREATE TABLE email_outbox(id INTEGER PRIMARY KEY,reservation_id INTEGER REFERENCES reservations(id),kind TEXT NOT NULL,payload TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'queued',attempts INTEGER NOT NULL DEFAULT 0,last_error TEXT,next_attempt_at TEXT,created_at TEXT NOT NULL,sent_at TEXT);
